import React, { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useAuth } from '@/contexts/AuthContext';
import { useToast } from '@/components/ui/use-toast';
import { motion, AnimatePresence } from 'framer-motion';
import { KeyRound, Users, ShieldCheck, ArrowRight, Loader2 } from 'lucide-react';

export default function VaultAccess({ onUnlocked }: { onUnlocked: (key: string) => void }) {
    const { session } = useAuth();
    const { toast } = useToast();

    // Step 1: Vault Identifier
    const [vaultCode, setVaultCode] = useState('');
    const [nomineeCount, setNomineeCount] = useState<number | null>(null);
    const [fetchingRequirements, setFetchingRequirements] = useState(false);

    // Step 2: Keys
    const [accessMethod, setAccessMethod] = useState<'owner' | 'nominees'>('owner');
    const [keyInput, setKeyInput] = useState('');
    const [nomineeKeys, setNomineeKeys] = useState<string[]>([]);
    const [loading, setLoading] = useState(false);

    const handleFetchRequirements = async () => {
        if (!vaultCode.trim()) return;
        setFetchingRequirements(true);
        try {
            const apiUrl = import.meta.env.VITE_API_URL || 'http://localhost:8000';
            const response = await fetch(`${apiUrl}/vault/${vaultCode}/requirements`, {
                headers: {
                    'Content-Type': 'application/json',
                }
            });

            if (!response.ok) {
                const errData = await response.json().catch(() => ({}));
                throw new Error(errData.detail || 'Vault not found or invalid identifier.');
            }

            const data = await response.json();
            setNomineeCount(data.nominee_count);

            // Initialize nominee keys array
            if (data.nominee_count > 0) {
                setNomineeKeys(Array(data.nominee_count).fill(''));
            } else {
                setAccessMethod('owner');
            }

        } catch (err: any) {
            console.error(err);
            toast({ title: 'Error', description: err.message, variant: 'destructive' });
        } finally {
            setFetchingRequirements(false);
        }
    };

    const handleNomineeKeyChange = (index: number, value: string) => {
        const newKeys = [...nomineeKeys];
        newKeys[index] = value;
        setNomineeKeys(newKeys);
    };

    const handleUnlock = async () => {
        setLoading(true);
        try {
            const apiUrl = import.meta.env.VITE_API_URL || 'http://localhost:8000';

            const payload: any = { vault_code: vaultCode };

            if (accessMethod === 'owner') {
                if (!keyInput.trim()) throw new Error("Owner secret key is required.");
                payload.secret_key = keyInput;
            } else {
                if (nomineeKeys.some(k => !k.trim())) throw new Error("All nominee keys are required.");
                payload.nominee_keys = nomineeKeys;
            }

            const response = await fetch(`${apiUrl}/verification/vault-access`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(payload)
            });

            if (!response.ok) {
                if (response.status === 429) {
                    throw new Error('Too many attempts. Please try again later.');
                }
                const errData = await response.json().catch(() => ({}));
                throw new Error(errData.detail || 'Invalid credentials or keys provided.');
            }

            toast({ title: 'Vault Unlocked', description: 'Your session is active in memory.' });

            // Unlocked with owner key or first nominee key (as a reference key for the frontend)
            onUnlocked(accessMethod === 'owner' ? keyInput : nomineeKeys[0]);
        } catch (err: unknown) {
            console.error(err);
            toast({ title: 'Access Denied', description: (err as Error).message, variant: 'destructive' });
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="flex flex-col items-center justify-center p-6 border border-zinc-200 dark:border-zinc-800 rounded-2xl bg-white dark:bg-zinc-950 shadow-sm mt-8 max-w-lg mx-auto w-full">
            <div className="w-12 h-12 rounded-full bg-blue-500/10 flex items-center justify-center mb-4">
                <ShieldCheck className="w-6 h-6 text-blue-500" />
            </div>
            <h2 className="text-2xl font-bold mb-2 text-zinc-900 dark:text-zinc-100">Unlock Your Vault</h2>

            <AnimatePresence mode="wait">
                {nomineeCount === null ? (
                    <motion.div
                        key="step-1"
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -10 }}
                        className="w-full flex flex-col items-center"
                    >
                        <p className="mb-6 max-w-sm text-center text-zinc-500 text-sm">
                            Enter your Vault Identifier to begin securely accessing your sealed assets.
                        </p>
                        <div className="flex flex-col w-full max-w-sm space-y-4">
                            <Input
                                type="text"
                                placeholder="Vault Identifier (e.g. TRX-ABCD-1234)"
                                value={vaultCode}
                                onChange={(e) => setVaultCode(e.target.value.toUpperCase())}
                                className="font-mono text-center uppercase h-12 tracking-wider"
                            />
                            <Button
                                onClick={handleFetchRequirements}
                                disabled={fetchingRequirements || !vaultCode.trim()}
                                className="w-full h-12 font-medium"
                            >
                                {fetchingRequirements ? <Loader2 className="w-5 h-5 animate-spin" /> : (
                                    <>Continue <ArrowRight className="w-4 h-4 ml-2" /></>
                                )}
                            </Button>
                        </div>
                    </motion.div>
                ) : (
                    <motion.div
                        key="step-2"
                        initial={{ opacity: 0, y: 10 }}
                        animate={{ opacity: 1, y: 0 }}
                        className="w-full flex flex-col items-center"
                    >
                        {nomineeCount > 0 ? (
                            <div className="w-full mb-6 mt-2">
                                <div className="flex p-1 bg-zinc-100 dark:bg-zinc-900 rounded-lg">
                                    <button
                                        onClick={() => setAccessMethod('owner')}
                                        className={`flex-1 flex justify-center items-center py-2 text-sm font-medium rounded-md transition-all ${accessMethod === 'owner' ? 'bg-white dark:bg-zinc-800 shadow shadow-zinc-200 dark:shadow-none text-zinc-900 dark:text-zinc-100' : 'text-zinc-500 hover:text-zinc-900 dark:hover:text-zinc-300'}`}
                                    >
                                        <KeyRound className="w-4 h-4 mr-2" />
                                        Owner Access
                                    </button>
                                    <button
                                        onClick={() => setAccessMethod('nominees')}
                                        className={`flex-1 flex justify-center items-center py-2 text-sm font-medium rounded-md transition-all ${accessMethod === 'nominees' ? 'bg-white dark:bg-zinc-800 shadow shadow-zinc-200 dark:shadow-none text-zinc-900 dark:text-zinc-100' : 'text-zinc-500 hover:text-zinc-900 dark:hover:text-zinc-300'}`}
                                    >
                                        <Users className="w-4 h-4 mr-2" />
                                        Nominee Access
                                    </button>
                                </div>
                            </div>
                        ) : (
                            <p className="mb-6 max-w-sm text-center text-zinc-500 text-sm">
                                Enter the Owner Secret Key for vault <span className="font-mono text-zinc-900 dark:text-zinc-300">{vaultCode}</span>
                            </p>
                        )}

                        <div className="flex flex-col w-full max-w-sm space-y-4">
                            {accessMethod === 'owner' ? (
                                <Input
                                    type="password"
                                    placeholder="Enter Owner Secret Key"
                                    value={keyInput}
                                    onChange={(e) => setKeyInput(e.target.value)}
                                    className="font-mono text-sm w-full h-11"
                                />
                            ) : (
                                <div className="space-y-3">
                                    <p className="text-xs text-center text-info mb-2 font-medium">
                                        This vault requires all {nomineeCount} nominee designated keys to unlock.
                                    </p>
                                    {nomineeKeys.map((key, index) => (
                                        <div key={index} className="relative">
                                            <Input
                                                type="password"
                                                placeholder={`Nominee Key ${index + 1}`}
                                                value={key}
                                                onChange={(e) => handleNomineeKeyChange(index, e.target.value)}
                                                className="font-mono text-sm w-full h-11 pl-10"
                                            />
                                            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400 font-mono text-xs font-bold">
                                                #{index + 1}
                                            </span>
                                        </div>
                                    ))}
                                </div>
                            )}

                            <div className="pt-2 flex flex-col gap-3">
                                <Button
                                    onClick={handleUnlock}
                                    disabled={loading}
                                    className="w-full h-11 font-medium bg-blue-600 hover:bg-blue-700 text-white"
                                >
                                    {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : 'Unlock Vault'}
                                </Button>
                                <Button
                                    variant="ghost"
                                    onClick={() => { setNomineeCount(null); setKeyInput(''); setNomineeKeys([]); }}
                                    disabled={loading}
                                >
                                    Cancel
                                </Button>
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}

import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { supabase } from "@/lib/supabase";
import { toast } from "sonner";
import "./Auth.css";

export default function Auth() {
    const [isLogin, setIsLogin] = useState(true);
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [fullName, setFullName] = useState("");
    const [loading, setLoading] = useState(false);
    const [showForgotPassword, setShowForgotPassword] = useState(false);
    const navigate = useNavigate();

    const handleGoogleLogin = async (e: React.MouseEvent) => {
        e.preventDefault();
        setLoading(true);
        try {
            const { error } = await supabase.auth.signInWithOAuth({
                provider: "google",
                options: {
                    redirectTo: `${window.location.origin}/dashboard`,
                },
            });
            if (error) {
                toast.error(error.message);
            }
        } catch (err: any) {
            toast.error("Google sign-in failed. Please try again.");
        } finally {
            setLoading(false);
        }
    };

    const handleEmailAuth = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);

        try {
            if (isLogin) {
                // Sign in
                const { error } = await supabase.auth.signInWithPassword({
                    email,
                    password,
                });
                if (error) {
                    toast.error(error.message);
                    return;
                }
                toast.success("Signed in successfully!");
                navigate("/dashboard");
            } else {
                // Sign up
                const { error } = await supabase.auth.signUp({
                    email,
                    password,
                    options: {
                        data: {
                            full_name: fullName,
                        },
                    },
                });
                if (error) {
                    toast.error(error.message);
                    return;
                }
                toast.success("Account created! Please check your email to verify, then sign in.");
                setIsLogin(true);
                setPassword("");
            }
        } catch (err: any) {
            toast.error("An unexpected error occurred. Please try again.");
        } finally {
            setLoading(false);
        }
    };

    const handleForgotPassword = async (e: React.MouseEvent) => {
        e.preventDefault();
        if (!email) {
            toast.error("Please enter your email address first.");
            return;
        }
        setLoading(true);
        try {
            const { error } = await supabase.auth.resetPasswordForEmail(email, {
                redirectTo: `${window.location.origin}/auth`,
            });
            if (error) {
                toast.error(error.message);
                return;
            }
            toast.success("Password reset email sent! Check your inbox.");
        } catch (err: any) {
            toast.error("Failed to send reset email. Please try again.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="auth-wrapper">
            <video src="/bglogin.mp4" autoPlay loop muted playsInline className="vid-bg" />
            <div className="bg-overlay"></div>

            <div className="orb orb1"></div>
            <div className="orb orb2"></div>
            <div className="orb orb3"></div>

            <div className="card">
                <div className="brand">
                    <img src="/logo.png" alt="Trustix Logo" className="w-10 h-10 object-contain" />
                    <span className="brand-name">TRUSTIX</span>
                </div>

                <h1>{isLogin ? "Welcome back" : "Create an account"}</h1>
                <p className="subtitle">
                    {isLogin ? "Sign in to continue your journey" : "Join us to secure your digital legacy"}
                </p>

                {/* Google OAuth Button */}
                <a
                    href="#"
                    className={`btn-google ${loading ? "opacity-50 pointer-events-none" : ""}`}
                    onClick={handleGoogleLogin}
                >
                    <svg className="google-logo" width="20" height="20" viewBox="0 0 48 48">
                        <path
                            fill="#EA4335"
                            d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"
                        />
                        <path
                            fill="#4285F4"
                            d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"
                        />
                        <path
                            fill="#FBBC05"
                            d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"
                        />
                        <path
                            fill="#34A853"
                            d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"
                        />
                        <path fill="none" d="M0 0h48v48H0z" />
                    </svg>
                    {loading ? "Please wait..." : isLogin ? "Continue with Google" : "Sign up with Google"}
                </a>

                <div className="divider">
                    <span>or</span>
                </div>

                <form onSubmit={handleEmailAuth}>
                    {!isLogin && (
                        <div className="field">
                            <label>Full Name</label>
                            <input
                                type="text"
                                placeholder="John Doe"
                                value={fullName}
                                onChange={(e) => setFullName(e.target.value)}
                                required
                                disabled={loading}
                            />
                        </div>
                    )}
                    <div className="field">
                        <label>Email</label>
                        <input
                            type="email"
                            placeholder="you@example.com"
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            required
                            disabled={loading}
                        />
                    </div>
                    <div className="field">
                        <label>Password</label>
                        <input
                            type="password"
                            placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            required
                            minLength={6}
                            disabled={loading}
                        />
                    </div>

                    {isLogin && (
                        <a
                            href="#"
                            className="forgot"
                            onClick={handleForgotPassword}
                        >
                            Forgot password?
                        </a>
                    )}

                    <button type="submit" className={`btn-submit ${loading ? "opacity-70" : ""}`} disabled={loading}>
                        {loading ? (
                            <span className="flex items-center justify-center gap-2">
                                <span className="inline-block h-4 w-4 rounded-full border-2 border-white border-t-transparent animate-spin" />
                                {isLogin ? "Signing in..." : "Creating account..."}
                            </span>
                        ) : (
                            isLogin ? "Sign In" : "Create Account"
                        )}
                    </button>
                </form>

                <p className="footer">
                    {isLogin ? "Don't have an account? " : "Already have an account? "}
                    <a
                        href="#"
                        onClick={(e) => {
                            e.preventDefault();
                            setIsLogin(!isLogin);
                            setPassword("");
                        }}
                    >
                        {isLogin ? "Create one" : "Sign in"}
                    </a>
                </p>
            </div>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { useAuth } from '@/contexts/AuthContext';
import { DashboardLayout } from "@/components/DashboardLayout";
import VaultInit from '@/components/vault/VaultInit';
import VaultAccess from '@/components/vault/VaultAccess';
import VaultDashboard from '@/components/vault/VaultDashboard';
import { ShieldAlert } from 'lucide-react';

export default function ZkVaultPage() {
    const { session } = useAuth();
    const location = useLocation();

    // Check if we came from the dashboard popup with a key already unlocked
    const initialKey = location.state?.encryptionKey || null;

    const [status, setStatus] = useState<'loading' | 'uninitialized' | 'locked' | 'unlocked'>(initialKey ? 'unlocked' : 'loading');
    const [encryptionKey, setEncryptionKey] = useState<string | null>(initialKey);

    useEffect(() => {
        const checkStatus = async () => {
            if (!session) return;
            if (initialKey) return; // already unlocked, skip check
            try {
                const apiUrl = import.meta.env.VITE_API_URL || 'http://localhost:8000';
                const res = await fetch(`${apiUrl}/zk-vault/status`, {
                    credentials: 'include',
                    headers: { Authorization: `Bearer ${session.access_token}` }
                });
                if (res.ok) {
                    const data = await res.json();
                    if (data.initialized) {
                        setStatus('locked');
                    } else {
                        setStatus('uninitialized');
                    }
                } else {
                    setStatus('uninitialized');
                }
            } catch (err) {
                console.error(err);
                setStatus('locked'); // Default to locked on error to be safe
            }
        };
        checkStatus();
    }, [session]);

    return (
        <DashboardLayout>
            <div className="space-y-6">
                <div className="flex items-center justify-between mb-8">
                    <div className="flex items-center gap-4">
                        <div className="h-12 w-12 flex items-center justify-center rounded-xl bg-primary/10 text-primary">
                            <ShieldAlert size={24} />
                        </div>
                        <div>
                            <h1 className="page-title">ZK Vault</h1>
                            <p className="page-subtitle">True Zero-Knowledge Secret Storage</p>
                        </div>
                    </div>
                </div>

                <div>
                    {status === 'loading' && <div className="p-12 text-center text-muted-foreground animate-pulse">Establishing secure connection...</div>}
                    {status === 'uninitialized' && <VaultInit onInitialized={() => setStatus('locked')} />}
                    {status === 'locked' && <VaultAccess onUnlocked={(key) => { setEncryptionKey(key); setStatus('unlocked'); }} />}
                    {status === 'unlocked' && encryptionKey && <VaultDashboard encryptionKey={encryptionKey} onLock={() => { setEncryptionKey(null); setStatus('locked'); }} />}
                </div>
            </div>
        </DashboardLayout>
    );
}

